1: /**
2:  * Patch diagram parser.
3:  *
4:  * At build time, Vite's nearley plugin compiles patch.ne into an ES module
5:  * that exports a compiled grammar object. At runtime, the nearley parser
6:  * runtime (`nearley` package) uses that grammar to parse diagram text.
7:  *
8:  * The parser populates db via setData() with the parsed AST.
9:  */
10: // eslint-disable-next-line @typescript-eslint/no-explicit-any
11: import nearley from 'nearley';
12: import type { PatchAST } from './types.js';
13: import db from './db.js';
14: import { log } from './mermaidUtils.js';
15: 
16: // Grammar compiled from patch.ne by scripts/compileGrammar.cjs
17: // @ts-expect-error — generated JS file, no types
18: import grammar from './grammar/patch.grammar.js';
19: 
20: function parsePatch(text: string): PatchAST {
21:   const normalized = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').trim();
22:   const parser = new nearley.Parser(nearley.Grammar.fromCompiled(grammar));
23:   parser.feed(normalized);
24: 
25:   if (!parser.results || parser.results.length === 0) {
26:     throw new Error('Patch: no parse result — check diagram syntax');
27:   }
28: 
29:   const statements: unknown[] = parser.results[0];
30:   const modules = statements.filter(
31:     (s): s is { type: 'module'; name: string; ports: unknown[] } =>
32:       (s as { type: string }).type === 'module'
33:   );
34:   const nodes = statements.filter(
35:     (s): s is { type: 'node'; function: string; name: string; label: string | null } =>
36:       (s as { type: string }).type === 'node'
37:   );
38:   const connections = statements.filter(
39:     (s): s is { type: 'connection' | 'dangling' } =>
40:       (s as { type: string }).type === 'connection' ||
41:       (s as { type: string }).type === 'dangling'
42:   );
43: 
44:   return { modules, nodes, connections } as PatchAST;
45: }

1: /**
2:  * scripts/compileGrammar.cjs
3:  *
4:  * Pre-compiles patch.ne → src/grammar/patch.grammar.js (ESM).
5:  * Run via: node scripts/compileGrammar.cjs
6:  * Or automatically via the `prebuild` / `pretest` npm scripts.
7:  */
8: 'use strict';
9: const nearley  = require('nearley');
10: const compile  = require('nearley/lib/compile');
11: const generate = require('nearley/lib/generate');
12: const boot     = require('nearley/lib/nearley-language-bootstrapped');
13: const fs   = require('fs');
14: const path = require('path');
15: 
16: const src = fs.readFileSync(
17:   path.join(__dirname, '../src/grammar/patch.ne'),
18:   'utf-8'
19: );
20: 
21: const parser = new nearley.Parser(nearley.Grammar.fromCompiled(boot));
22: parser.feed(src);
23: 
24: if (!parser.results || parser.results.length === 0) {
25:   console.error('Grammar compilation failed — no parse result.');
26:   process.exit(1);
27: }
28: 
29: const compiled  = compile(parser.results[0], {});
30: const generated = generate(compiled, 'grammar');
31: 
32: // Extract the IIFE body robustly (nearley prepends comment lines before the IIFE)
33: const iifStart = generated.indexOf('(function () {');
34: const iifEnd   = generated.lastIndexOf('})();');
35: if (iifStart === -1 || iifEnd === -1) {
36:   console.error('Grammar compilation failed — could not locate IIFE wrapper.');
37:   process.exit(1);
38: }
39: const iifBody = generated.slice(iifStart + '(function () {\n'.length, iifEnd);
40: 
41: // Strip the CJS/global export block (last if-block before closing IIFE brace)
42: const withoutCjs = iifBody
43:   .replace(/\nif \(typeof module[^}]*\}\s*\}\s*\n?$/s, '')
44:   .trimEnd();
45: 
46: // nearley emits `function id(x) { return x[0]; }` then later another identical
47: // `function id(d) { return d[0]; }` from the grammar builtins. Remove the first
48: // occurrence so the ESM module has no duplicate declaration.
49: const deduped = withoutCjs.replace(/^function id\(x\) \{ return x\[0\]; \}\n[ \t]*\n?/, '');
50: 
51: const esm = `// AUTO-GENERATED — do not edit. Run: node scripts/compileGrammar.cjs\n// Source: src/grammar/patch.ne\n\n${deduped}\n\nexport { grammar };\nexport default grammar;\n`;
52: 
53: const outPath = path.join(__dirname, '../src/grammar/patch.grammar.js');
54: fs.writeFileSync(outPath, esm, 'utf-8');
55: console.log('[patch] Grammar compiled →', path.relative(process.cwd(), outPath));
